const SECRET = '__RECHNER_GEHEIMNIS__';
const item = $input.first().json;
const h = item.headers || {};
const q = item.query || {};

// Nur Aufrufe, die von unserem Server kommen
if (h['x-klinovum-secret'] !== SECRET) return [];
// Nur echte Browser-Aufrufe der Seite, keine Skripte oder Link-Scanner
if ((h['sec-fetch-dest'] || '') !== 'document') return [];
const ua = String(h['user-agent'] || '');
if (/bot|crawl|spider|preview|scanner|headless|python|curl|wget|go-http|java\/|okhttp|axios|node-fetch|safelinks|barracuda|proofpoint|mimecast|trendmicro|zscaler/i.test(ua)) return [];

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const lid = String(q.lid || '').trim();
const email = String(q.e || '').trim().toLowerCase();
let mode = null;
if (UUID.test(lid)) mode = 'lid';
else if (EMAIL.test(email) && email.length < 200) mode = 'email';
else return [];

// Ein Eintrag je Person und sechs Stunden (Neuladen und Weiterklicken erzeugt keine Notizflut)
const key = mode === 'lid' ? lid : email;
const sd = $getWorkflowStaticData('global');
sd.seen = sd.seen || {};
const now = Date.now();
for (const k of Object.keys(sd.seen)) if (now - sd.seen[k] > 24 * 3600 * 1000) delete sd.seen[k];
if (sd.seen[key] && now - sd.seen[key] < 6 * 3600 * 1000) return [];
sd.seen[key] = now;

const clean = (s, n) => String(s || '').replace(/[\r\n]+/g, ' ').slice(0, n);
const d = new Date(now);
const datum = d.toLocaleDateString('de-DE', { timeZone: 'Europe/Berlin' });
const uhr = d.toLocaleTimeString('de-DE', { timeZone: 'Europe/Berlin', hour: '2-digit', minute: '2-digit' });
const iso = d.toLocaleDateString('sv-SE', { timeZone: 'Europe/Berlin' });
return [{ json: { mode, lid, email, haus: clean(q.haus, 80), plaetze: clean(q.plaetze, 10), datum, uhr, iso } }];

const ctx = $('Prüfen').first().json;
const r = $input.first().json;
const id = r && r.data && r.data.id && r.data.id.record_id;
if (!id) return [];
const zeilen = [
  'Der Vertriebsautopilot hat gesehen: Der Ausfall-Rechner wurde über den persönlichen Link geöffnet.',
  'Zeit: ' + ctx.datum + ', ' + ctx.uhr + ' Uhr',
];
if (ctx.haus) zeilen.push('Haus laut Link: ' + ctx.haus);
if (ctx.plaetze) zeilen.push('Plätze laut Link: ' + ctx.plaetze);
zeilen.push('Hinweis: Das zeigt das Öffnen der Seite, nicht, ob der Rechner ausgefüllt wurde. Die Eingaben bleiben im Browser des Besuchers.');
return [{ json: { ...ctx, recordId: id, noteContent: zeilen.join('\n') } }];
